                          resid(idet) = resid(idet) + I2A_vooo(m,b,i,j) * xbuf(m,k,a,c)
                          resid(idet) = resid(idet) + I2A_vooo(m,c,i,j) * xbuf(m,k,b,a)
                          resid(idet) = resid(idet) + I2A_vooo(m,a,k,j) * xbuf(m,i,b,c)
