                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        e = t4_excits_buff(jdet,2); l = t4_excits_buff(jdet,5); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h2a(ooov) | lmikaebc >
                        !hmatel = h2a_ooov(l,m,j,e)
                        hmatel = h2a_ooov(l,m,j,e)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! BCDKL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaaa, 5, (/2,3,4,7,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3a_excits,t4_excits_buff,&
                  !$omp t3a_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H2A_ooov,&
                  !$omp noa,nua,n3aaa),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aaa
                     a = t3a_excits(idet,1); b = t3a_excits(idet,2); c = t3a_excits(idet,3);
                     i = t3a_excits(idet,4); j = t3a_excits(idet,5); k = t3a_excits(idet,6);
                     ! (1)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        d = t4_excits_buff(jdet,1); l = t4_excits_buff(jdet,5); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h2a(ooov) | lmijdabc >
                        !hmatel = h2a_ooov(l,m,k,d)
                        hmatel = h2a_ooov(l,m,k,d)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (ik)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,j,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        d = t4_excits_buff(jdet,1); l = t4_excits_buff(jdet,5); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h2a(ooov) | lmjkdabc >
                        !hmatel = h2a_ooov(l,m,i,d)
                        hmatel = h2a_ooov(l,m,i,d)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                     ! (jk)
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,k/), 5, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        d = t4_excits_buff(jdet,1); l = t4_excits_buff(jdet,5); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h2a(ooov) | lmikdabc >
                        !hmatel = -h2a_ooov(l,m,j,d)
                        hmatel = -h2a_ooov(l,m,j,d)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
