                  allocate(t4_amps_buff(n4aaab),t4_excits_buff(n4aaab,8))
                  t4_amps_buff(:) = t4b_amps(:)
                  t4_excits_buff(:,:) = t4b_excits(:,:)
                  ! allocate sorting arrays (can be reused for each permutation)
                  kdims(1:6) = (/nua,nua,nub,noa,noa,nob/)
                  kchain(1:6) = (/.false.,.true.,.false.,.false.,.true.,.false./)
                  !!! ABDIJL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 6, (/1,2,4,5,6,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t4_excits_buff,&
                  !$omp t3b_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H1A_ov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j,k/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        f = t4_excits_buff(jdet,3); n = t4_excits_buff(jdet,7);
                        ! compute < ijkabc | h1a(ov) | ijnk~abfc~ >
                        !hmatel = h1a_ov(n,f)
                        hmatel = h1a_ov(n,f)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! ACDIJL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 6, (/1,3,4,5,6,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t4_excits_buff,&
                  !$omp t3b_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H1A_ov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j,k/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        e = t4_excits_buff(jdet,2); n = t4_excits_buff(jdet,7);
                        ! compute < ijkabc | h1a(ov) | ijnk~aebc~ >
                        !hmatel = -h1a_ov(n,e)
                        hmatel = -h1a_ov(n,e)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! BCDIJL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 6, (/2,3,4,5,6,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t4_excits_buff,&
                  !$omp t3b_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H1A_ov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j,k/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        d = t4_excits_buff(jdet,1); n = t4_excits_buff(jdet,7);
                        ! compute < ijkabc | h1a(ov) | ijnk~dabc~ >
                        !hmatel = h1a_ov(n,d)
                        hmatel = h1a_ov(n,d)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! ABDIKL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 6, (/1,2,4,5,7,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t4_excits_buff,&
                  !$omp t3b_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H1A_ov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
                  do idet = 1, n3aab
                     a = t3b_excits(idet,1); b = t3b_excits(idet,2); c = t3b_excits(idet,3);
                     i = t3b_excits(idet,4); j = t3b_excits(idet,5); k = t3b_excits(idet,6);
                     idx = pspace_find(block_key, nblock, pspace_key((/a,b,c,i,j,k/), 6, kdims, kchain))
                     if (idx/=0) then
                     do jdet = block_off(idx), block_off(idx+1)-1
                        f = t4_excits_buff(jdet,3); m = t4_excits_buff(jdet,6);
                        ! compute < ijkabc | h1a(ov) | imjk~abfc~ >
                        !hmatel = -h1a_ov(m,f)
                        hmatel = -h1a_ov(m,f)
                        resid(idet) = resid(idet) + hmatel * t4_amps_buff(jdet)
                     end do
                     end if
                  end do
                  !$omp end do
                  !$omp end parallel
                  !!!! END OMP PARALLEL SECTION !!!!
                  !!! ACDIKL LOOP !!!
                  call sort_pspace(t4_excits_buff, t4_amps_buff, n4aaab, 6, (/1,3,4,5,7,8/), kdims, kchain, nblock, block_key, block_off)
                  !!!! BEGIN OMP PARALLEL SECTION !!!!
                  !$omp parallel shared(resid,&
                  !$omp t3b_excits,t4_excits_buff,&
                  !$omp t3b_amps,t4_amps_buff,&
                  !$omp nblock,block_key,block_off,kdims,kchain,&
                  !$omp H1A_ov,&
                  !$omp noa,nua,nob,nub,n3aab),&
                  !$omp private(hmatel,a,b,c,d,i,j,k,l,e,f,m,n,idet,jdet,&
                  !$omp idx)
                  !$omp do schedule(static)
