                  real(kind=8), intent(in) :: H2A_oooo(noa,noa,noa,noa)
                  real(kind=8), intent(in) :: H2A_ooov(noa,noa,noa,nua)
                  real(kind=8), intent(in) :: H2A_vooo(nua,noa,noa,noa)
                  real(kind=8), intent(in) :: H2A_voov(nua,noa,noa,nua)
