                           end do
                        end do
                     end do
                  end do
                  allocate(h2b_voov_1302(nob,nub,nua,noa))
                  do p4 = 1, noa
                     do p3 = 1, nua
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2b_voov_1302(p1,p2,p3,p4) = H2B_voov(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_vovv_2301(nua,nua,nua,noa))
                  do p4 = 1, noa
                     do p3 = 1, nua
                        do p2 = 1, nua
                           do p1 = 1, nua
                              h2a_vovv_2301(p1,p2,p3,p4) = H2A_vovv(p3,p4,p1,p2)
                           end do
                        end do
