                  allocate(h2a_ooov_1302(noa,nua,noa,noa))
                  do p4 = 1, noa
                     do p3 = 1, noa
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2a_ooov_1302(p1,p2,p3,p4) = H2A_ooov(p3,p1,p4,p2)
                           end do
