                  allocate(h2a_vovv_1302(noa,nua,nua,nua))
                  do p4 = 1, nua
                     do p3 = 1, nua
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2a_vovv_1302(p1,p2,p3,p4) = H2A_vovv(p3,p1,p4,p2)
                           end do
