                     end do
                  end do
                  allocate(h2c_oovv_1302(nob,nub,nob,nub))
                  do p4 = 1, nub
                     do p3 = 1, nob
                        do p2 = 1, nub
                           do p1 = 1, nob
                              h2c_oovv_1302(p1,p2,p3,p4) = H2C_oovv(p3,p1,p4,p2)
                           end do
                        end do
                     end do
                  end do
                  allocate(h2a_voov_1023(noa,nua,noa,nua))
                  do p4 = 1, nua
                     do p3 = 1, noa
                        do p2 = 1, nua
                           do p1 = 1, noa
                              h2a_voov_1023(p1,p2,p3,p4) = H2A_voov(p2,p1,p3,p4)
                           end do
