                                 noa, nua, nob, nub)
                  ! (I(T2, T3) * T3)_C terms
                  call t4a_p_b3(resid, t4a_amps, t4a_excits, t3a_amps, t3a_excits, t3b_amps,&
                                t3b_excits, t2a, H2A_ooov, H2A_oovv, h2a_vovv_2301, h2a_ooov_1302,&
                                h2a_vovv_1302, h2a_oovv_1302, h2b_oovv_0213, h2b_ooov_1302, h2b_vovv_1302, h2c_oovv_1302,&
                                n4aaaa, n3aaa, n3aab, noa, nua, nob,&
                                nub)
                  ! (I(T2, T4) * T2)_C and (H * T2 * T2)_C terms
                  call t4a_p_b2(resid, t4a_amps, t4a_excits, t4b_amps, t4b_excits, t2a,&
                                h2a_voov_1023, h2a_oooo_1023, h2a_oovv_1023, H2B_oovv, h2a_vvvv_3012, h2a_oovv_3012,&
                                h2b_oovv_2013, n4aaaa, n4aaab, noa, nua, nob,&
                                nub)
                  deallocate(h2a_vvov_3012)
                  deallocate(h2a_vooo_1023)
                  deallocate(h2a_vvvv_2301)
                  deallocate(h1a_vv_10)
                  deallocate(h2a_voov_1302)
                  deallocate(h2b_voov_1302)
                  deallocate(h2a_vovv_2301)
                  deallocate(h2a_ooov_1302)
                  deallocate(h2a_vovv_1302)
                  deallocate(h2a_oovv_1302)
                  deallocate(h2b_oovv_0213)
                  deallocate(h2b_ooov_1302)
                  deallocate(h2b_vovv_1302)
                  deallocate(h2c_oovv_1302)
                  deallocate(h2a_voov_1023)
                  deallocate(h2a_oooo_1023)
                  deallocate(h2a_oovv_1023)
                  deallocate(h2a_vvvv_3012)
                  deallocate(h2a_oovv_3012)
                  deallocate(h2b_oovv_2013)

                  ! Update t4 vector
                  !$omp parallel shared(resid,t4a_excits,t4a_amps,fA_oo,fA_vv,fB_oo,fB_vv,n4aaaa,shift),&
                  !$omp private(idet,a,b,c,d,i,j,k,l,denom)
                  !$omp do schedule(static)
                  do idet = 1, n4aaaa
                      a = t4a_excits(idet,1); b = t4a_excits(idet,2); c = t4a_excits(idet,3); d = t4a_excits(idet,4);
                      i = t4a_excits(idet,5); j = t4a_excits(idet,6); k = t4a_excits(idet,7); l = t4a_excits(idet,8);
                      denom = fA_oo(i,i) + fA_oo(j,j) + fA_oo(k,k) + fA_oo(l,l) - fA_vv(a,a) - fA_vv(b,b) - fA_vv(c,c) - fA_vv(d,d)
                      resid(idet) = resid(idet)/(denom - shift)
                      t4a_amps(idet) = t4a_amps(idet) + resid(idet)
                  end do
                  !$omp end do
                  !$omp end parallel

              end subroutine update_t4a_p

