                  deallocate(h2b_oovv_2013)
                  deallocate(h2a_vvvv_3012)
                  deallocate(h2c_vvvv_3012)
                  deallocate(h2b_oovv_3012)
                  deallocate(h2c_oovv_3012)

                  ! Update t4 vector
                  !$omp parallel shared(resid,t4c_excits,t4c_amps,fA_oo,fA_vv,fB_oo,fB_vv,n4aabb,shift),&
                  !$omp private(idet,a,b,c,d,i,j,k,l,denom)
                  !$omp do schedule(static)
                  do idet = 1, n4aabb
                      a = t4c_excits(idet,1); b = t4c_excits(idet,2); c = t4c_excits(idet,3); d = t4c_excits(idet,4);
                      i = t4c_excits(idet,5); j = t4c_excits(idet,6); k = t4c_excits(idet,7); l = t4c_excits(idet,8);
                      denom = fA_oo(i,i) + fA_oo(j,j) + fB_oo(k,k) + fB_oo(l,l) - fA_vv(a,a) - fA_vv(b,b) - fB_vv(c,c) - fB_vv(d,d)
                      resid(idet) = resid(idet)/(denom - shift)
                      t4c_amps(idet) = t4c_amps(idet) + resid(idet)
                  end do
                  !$omp end do
                  !$omp end parallel

              end subroutine update_t4c_p

              subroutine update_t4d_p(resid,&
                                      t4d_amps, t4d_excits, t4c_amps, t4c_excits,&
                                      t4e_amps, t4e_excits, t3b_amps, t3b_excits,&
                                      t3c_amps, t3c_excits, t3d_amps, t3d_excits,&
                                      t2b, t2c, H1A_oo, H1A_vv,&
                                      H1B_oo, H1B_vv, H2A_ooov, H2A_voov,&
                                      H2A_vovv, H2B_oooo, H2B_ooov, H2B_oovo,&
                                      H2B_ovoo, H2B_ovov, H2B_ovvo, H2B_ovvv,&
                                      H2B_vooo, H2B_voov, H2B_vovo, H2B_vovv,&
                                      H2B_vvov, H2B_vvvo, H2B_vvvv, H2C_oooo,&
                                      H2C_ooov, H2C_vooo, H2C_voov, H2C_vovv,&
                                      H2C_vvov, H2C_vvvv, H2A_oovv, H2B_oovv,&
                                      H2C_oovv, fA_oo, fA_vv, fB_oo,&
                                      fB_vv, shift, n4abbb, n3aab,&
                                      n3abb, n3bbb, n4aabb, n4bbbb,&
                                      noa, nua, nob, nub)

                  integer, intent(in) :: n4abbb, n3aab, n3abb, n3bbb, n4aabb, n4bbbb, noa, nua, nob, nub
                  real(kind=8), intent(in) :: t4c_amps(n4aabb)
                  integer, intent(in) :: t4c_excits(n4aabb,8)
                  real(kind=8), intent(in) :: t4e_amps(n4bbbb)
                  integer, intent(in) :: t4e_excits(n4bbbb,8)
                  real(kind=8), intent(in) :: t3b_amps(n3aab)
                  integer, intent(in) :: t3b_excits(n3aab,6)
                  real(kind=8), intent(in) :: t3c_amps(n3abb)
                  integer, intent(in) :: t3c_excits(n3abb,6)
                  real(kind=8), intent(in) :: t3d_amps(n3bbb)
                  integer, intent(in) :: t3d_excits(n3bbb,6)
                  real(kind=8), intent(in) :: t2b(nua,nub,noa,nob)
                  real(kind=8), intent(in) :: t2c(nub,nub,nob,nob)
                  real(kind=8), intent(in) :: H1A_oo(noa,noa)
                  real(kind=8), intent(in) :: H1A_vv(nua,nua)
                  real(kind=8), intent(in) :: H1B_oo(nob,nob)
                  real(kind=8), intent(in) :: H1B_vv(nub,nub)
                  real(kind=8), intent(in) :: H2A_ooov(noa,noa,noa,nua)
                  real(kind=8), intent(in) :: H2A_voov(nua,noa,noa,nua)
                  real(kind=8), intent(in) :: H2A_vovv(nua,noa,nua,nua)
                  real(kind=8), intent(in) :: H2B_oooo(noa,nob,noa,nob)
                  real(kind=8), intent(in) :: H2B_ooov(noa,nob,noa,nub)
                  real(kind=8), intent(in) :: H2B_oovo(noa,nob,nua,nob)
                  real(kind=8), intent(in) :: H2B_ovoo(noa,nub,noa,nob)
                  real(kind=8), intent(in) :: H2B_ovov(noa,nub,noa,nub)
