                  end do
                  allocate(h2b_oovv_3012(nub,noa,nob,nua))
                  do p4 = 1, nua
                     do p3 = 1, nob
                        do p2 = 1, noa
                           do p1 = 1, nub
                              h2b_oovv_3012(p1,p2,p3,p4) = H2B_oovv(p2,p3,p4,p1)
                           end do
                        end do
                     end do
                  end do

                  ! (H(2) * T3 + H(2) * T4)_C linear terms
                  call t4e_p_lin(resid, t4e_amps, t4e_excits, t3d_amps, t3d_excits, t4d_amps,&
                                 t4d_excits, h2c_vvov_3012, h2c_vooo_1023, H2C_oooo, H1B_oo, h2c_vvvv_2301,&
                                 h1b_vv_10, h2c_voov_1302, h2b_ovvo_0213, n4bbbb, n3bbb, n4abbb,&
                                 noa, nua, nob, nub)
                  ! (I(T2, T3) * T3)_C terms
                  call t4e_p_b3(resid, t4e_amps, t4e_excits, t3c_amps, t3c_excits, t3d_amps,&
                                t3d_excits, t2c, H2C_ooov, H2C_oovv, h2c_vovv_2301, h2c_ooov_1302,&
                                h2c_vovv_1302, h2c_oovv_1302, h2b_oovv_1302, h2b_oovo_0213, h2b_ovvv_0213, h2a_oovv_1302,&
                                n4bbbb, n3abb, n3bbb, noa, nua, nob,&
                                nub)
                  ! (I(T2, T4) * T2)_C and (H * T2 * T2)_C terms
                  call t4e_p_b2(resid, t4e_amps, t4e_excits, t4d_amps, t4d_excits, t2c,&
                                h2c_voov_1023, h2c_oooo_1023, h2c_oovv_1023, h2b_oovv_1023, h2c_vvvv_3012, h2c_oovv_3012,&
                                h2b_oovv_3012, n4bbbb, n4abbb, noa, nua, nob,&
                                nub)
                  deallocate(h2c_vvov_3012)
                  deallocate(h2c_vooo_1023)
                  deallocate(h2c_vvvv_2301)
                  deallocate(h1b_vv_10)
                  deallocate(h2c_voov_1302)
                  deallocate(h2b_ovvo_0213)
                  deallocate(h2c_vovv_2301)
                  deallocate(h2c_ooov_1302)
                  deallocate(h2c_vovv_1302)
                  deallocate(h2c_oovv_1302)
                  deallocate(h2b_oovv_1302)
                  deallocate(h2b_oovo_0213)
                  deallocate(h2b_ovvv_0213)
                  deallocate(h2a_oovv_1302)
                  deallocate(h2c_voov_1023)
                  deallocate(h2c_oooo_1023)
                  deallocate(h2c_oovv_1023)
                  deallocate(h2b_oovv_1023)
                  deallocate(h2c_vvvv_3012)
                  deallocate(h2c_oovv_3012)
                  deallocate(h2b_oovv_3012)

                  ! Update t4 vector
                  !$omp parallel shared(resid,t4e_excits,t4e_amps,fA_oo,fA_vv,fB_oo,fB_vv,n4bbbb,shift),&
                  !$omp private(idet,a,b,c,d,i,j,k,l,denom)
                  !$omp do schedule(static)
                  do idet = 1, n4bbbb
                      a = t4e_excits(idet,1); b = t4e_excits(idet,2); c = t4e_excits(idet,3); d = t4e_excits(idet,4);
                      i = t4e_excits(idet,5); j = t4e_excits(idet,6); k = t4e_excits(idet,7); l = t4e_excits(idet,8);
                      denom = fB_oo(i,i) + fB_oo(j,j) + fB_oo(k,k) + fB_oo(l,l) - fB_vv(a,a) - fB_vv(b,b) - fB_vv(c,c) - fB_vv(d,d)
                      resid(idet) = resid(idet)/(denom - shift)
                      t4e_amps(idet) = t4e_amps(idet) + resid(idet)
                  end do
                  !$omp end do
                  !$omp end parallel

              end subroutine update_t4e_p

end module ccsdtq_p_loops
